export function humanSize(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${Math.ceil(bytes / 1024)} KB`;
  return `${(bytes / 1024 / 1024).toFixed(1)} MB`;
}

/**
 * Format `host:port`, bracketing the host if it is a bare (unbracketed) IPv6 literal,
 * so a v6 address doesn't render as the ambiguous `::1:80`. IPv4 and hostnames are
 * left as-is. Mirrors the Rust `util::address::format_host_port`.
 */
export function formatHostPort(host: string, port: number): string {
  const needsBrackets = host.includes(":") && !host.startsWith("[");
  return needsBrackets ? `[${host}]:${port}` : `${host}:${port}`;
}
import { expect, it } from "vitest";
import en from "@/locales/en.json";
import { SUPPORTED_LANGUAGES, LANGUAGE_LABELS } from "./i18n";

const locales = import.meta.glob<Record<string, unknown>>("../locales/*.json", {
  eager: true,
  import: "default",
});

function keys(value: Record<string, unknown>, prefix = ""): string[] {
  return Object.entries(value).flatMap(([name, entry]) => {
    const path = prefix ? `${prefix}.${name}` : name;
    return entry && typeof entry === "object" && !Array.isArray(entry)
      ? keys(entry as Record<string, unknown>, path)
      : [path];
  });
}

function values(
  value: Record<string, unknown>,
  prefix = "",
): Record<string, string> {
  return Object.fromEntries(
    Object.entries(value).flatMap(([name, entry]) => {
      const path = prefix ? `${prefix}.${name}` : name;
      return entry && typeof entry === "object" && !Array.isArray(entry)
        ? Object.entries(values(entry as Record<string, unknown>, path))
        : [[path, String(entry)]];
    }),
  );
}

function variables(value: string) {
  return [...value.matchAll(/{{\s*([\w-]+)\s*}}/g)]
    .map((match) => match[1])
    .sort();
}

it("keeps all supported locales aligned with the English interface", () => {
  const registered = [...SUPPORTED_LANGUAGES].sort();
  expect(
    Object.keys(locales)
      .map((path) => path.split("/").pop()!.replace(".json", ""))
      .sort(),
  ).toEqual(registered);
  expect(Object.keys(LANGUAGE_LABELS)).toEqual([...SUPPORTED_LANGUAGES]);
  const reference = keys(en).sort();
  for (const [path, locale] of Object.entries(locales)) {
    expect(keys(locale).sort(), path).toEqual(reference);
    const translated = values(locale);
    for (const [key, source] of Object.entries(values(en))) {
      expect(translated[key]?.trim(), `${path}: ${key}`).toBeTruthy();
      expect(variables(translated[key]), `${path}: ${key}`).toEqual(
        variables(source),
      );
    }
  }
});
import { defineConfig } from "vitest/config";
import react from "@vitejs/plugin-react";
import { fileURLToPath, URL } from "node:url";
import { loadHelp } from "../tools/help/load.mjs";

// https://vitejs.dev/config/
export default defineConfig(() => {
  return {
    define: {
      "import.meta.env.VITE_BUNDLED_PACK_IDS": JSON.stringify(""),
    },
    publicDir: false,
    plugins: [
      react(),
      {
        name: "mesh-talk-help-content",
        async buildStart() {
          await loadHelp({
            root: fileURLToPath(new URL("../", import.meta.url)),
          });
        },
      },
    ],
    resolve: {
      // Hooks and the renderer must share a runtime, including linked or
      // accidentally duplicated dependency trees in build caches.
      dedupe: ["react", "react-dom"],
      alias: {
        "@": fileURLToPath(new URL("./src", import.meta.url)),
      },
    },
    build: {
      outDir: "dist",
      // macOS 12 WKWebView can reject Radix's class static blocks, which Vite's
      // default Safari 16.4 target leaves intact.
      target: "safari15",
      rolldownOptions: {
        output: {
          codeSplitting: {
            groups: [
              {
                // Keep the growing offline language catalog separate from UI code.
                name: "locales",
                test: /[\\/]src[\\/]locales[\\/]/,
              },
              {
                name: "react-vendor",
                // Keep React, its renderer and scheduler together so the shared
                // startup chunk stays small as application features grow.
                test: /[\\/]node_modules[\\/](?:react|react-dom|scheduler)[\\/]/,
              },
            ],
          },
        },
      },
      // The sign-in shell and authenticated chat are separate chunks. Assets load locally in
      // Tauri, so a modestly higher limit than Vite's web default is appropriate here.
      chunkSizeWarningLimit: 700,
    },
    server: {
      port: Number(process.env.MESH_TALK_E2E_PORT ?? 5173),
      strictPort: true,
      // A dev-server reconnect can reload the page mid-test and erase mock
      // authentication state. Playwright never edits source while it runs.
      hmr: process.env.MESH_TALK_E2E === "1" ? false : undefined,
    },
    test: {
      environment: "node",
      globals: false,
      include: ["src/**/*.test.ts"],
      coverage: {
        provider: "v8",
        include: ["src/**/*.{ts,tsx}"],
        exclude: ["src/**/*.test.ts", "src/**/*.d.ts"],
        reporter: ["text", "json-summary", "lcov"],
        thresholds: {
          "src/store/**/*.ts": { lines: 70 },
        },
      },
    },
  };
});
